-- #1523: news posts in the database, so Staff write them on the site (#1230)
-- instead of in news.json through a PR and a deploy.
--
-- * news_posts: one row per post. Site-wide, no guild or team (#1364, #1517).
--   published_at null is a draft; anyone, signed in or not, reads a published
--   post, and only Staff read drafts. Staff write with plain table writes under
--   the rules below; today Staff is is_site_admin(), Admins and Moderators once
--   Staff ranks exist (#1520). slug is the post's address (/news/<slug>), kept
--   when the title is edited.
-- * news-pictures: a public bucket for cover and body pictures. Anyone views
--   through the public URL; only Staff upload, replace or remove one.
-- * Every news.json entry copied in as a published post: date, category,
--   version and pinned kept, the body as written, its first sentence as the
--   summary. news.json stays for the current site (js/news.js) until cutover.

create table public.news_posts (
  id integer generated by default as identity primary key,
  slug text not null unique check (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
  title text not null check (title ~ '\S'),
  category text not null check (category in ('Feature', 'Fix', 'Change', 'Announcement')),
  summary text not null check (summary ~ '\S'),
  body text not null default '',
  cover_path text,
  cover_caption text,
  version text,
  pinned boolean not null default false,
  published_at timestamp with time zone,
  written_by integer references public.people (id) on delete set null default public.my_person_id(),
  created_at timestamp with time zone not null default now(),
  updated_at timestamp with time zone not null default now()
);

create index news_posts_published_idx on public.news_posts (published_at desc) where published_at is not null;

comment on table public.news_posts is
  'News posts (#1523), site-wide. published_at null: a draft, which only Staff (is_site_admin()) read. Written by Staff on the site (#1230); the news.json entries were copied in by this table''s migration.';
comment on column public.news_posts.slug is
  'The post''s address, /news/<slug>, for links from Discord. Lowercase words joined by hyphens; kept when the title changes.';
comment on column public.news_posts.summary is
  'One line for the News timeline and the Guild home teaser.';
comment on column public.news_posts.body is
  'Simple formatting: ## headings, **bold**, - lists, [links](url) and ![pictures](url).';
comment on column public.news_posts.cover_path is
  'The cover picture''s path in the news-pictures bucket; null for none.';
comment on column public.news_posts.version is
  'The site version the post went out with, for the copied news.json entries; optional on a new post.';
comment on column public.news_posts.published_at is
  'When the post was published; null while it is a draft. The copied entries carry their news.json date at noon Eastern.';
comment on column public.news_posts.written_by is
  'The person who wrote the post: the caller, set on insert.';
comment on column public.news_posts.updated_at is
  'The last edit.';

alter table public.news_posts owner to postgres;
alter table public.news_posts enable row level security;

create trigger trg_news_posts_updated_at
  before update on public.news_posts
  for each row execute function public.set_updated_at();

create policy "Public read published news_posts" on public.news_posts for select
  using (published_at is not null or (select is_site_admin()));
create policy "Staff add news_posts" on public.news_posts for insert to authenticated
  with check ((select is_site_admin()) and written_by is not distinct from (select my_person_id()));
create policy "Staff edit news_posts" on public.news_posts for update to authenticated
  using ((select is_site_admin())) with check ((select is_site_admin()));
create policy "Staff delete news_posts" on public.news_posts for delete to authenticated
  using ((select is_site_admin()));
create policy "Claude readers read news_posts" on public.news_posts
  for select to claude_readers using (true);

revoke all on table public.news_posts from public, anon, authenticated, service_role;
grant select on table public.news_posts to anon, service_role;
grant select, insert, update, delete on table public.news_posts to authenticated;

-- Pictures. Public: a post's pictures load from the bucket's public URL with
-- no read rule. Storage itself refuses a file over 5 MB or of another type.
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('news-pictures', 'news-pictures', true, 5242880, array['image/png', 'image/jpeg', 'image/webp', 'image/gif'])
on conflict (id) do nothing;

create policy "Staff manage news pictures" on storage.objects for all to authenticated
  using (bucket_id = 'news-pictures' and (select public.is_site_admin()))
  with check (bucket_id = 'news-pictures' and (select public.is_site_admin()));

-- news.json, oldest first, so a later entry on the same day has the higher id.
insert into public.news_posts (slug, title, category, summary, body, version, pinned, published_at) values
  ($q$sign-up-now-shows-and-lets-you-edit-your-existing-submission$q$, $q$Sign Up now shows and lets you edit your existing submission$q$, 'Change', $q$Signing up when you've already submitted this season now shows your existing signup (status, class/spec, your note) with an Edit button instead of a blank form.$q$, $q$Signing up when you've already submitted this season now shows your existing signup (status, class/spec, your note) with an Edit button instead of a blank form. Anything not yet added to the roster or denied can be corrected without asking an officer.$q$, $q$3.36.0$q$, false, '2026-07-15 12:00 America/New_York'),
  ($q$search-recent-loot-by-item-name$q$, $q$Search Recent Loot by item name$q$, 'Feature', $q$The landing page's Recent Loot feed now has a search box -- type an item name to see every match for the current season instead of just the last 10 drops.$q$, $q$The landing page's Recent Loot feed now has a search box -- type an item name to see every match for the current season instead of just the last 10 drops.$q$, $q$3.37.0$q$, false, '2026-07-16 12:00 America/New_York'),
  ($q$new-history-tab-past-seasons-at-a-glance$q$, $q$New History tab: past seasons at a glance$q$, 'Feature', $q$A new History tab lists every archived season, newest first, with the season's total Mythic kill count and the date of its last boss kill.$q$, $q$A new History tab lists every archived season, newest first, with the season's total Mythic kill count and the date of its last boss kill.$q$, $q$3.39.0$q$, false, '2026-07-16 12:00 America/New_York'),
  ($q$meet-the-officers-new-bios-tab$q$, $q$Meet the officers: new Bios tab$q$, 'Feature', $q$A new Bios tab introduces the team's raid officers -- photo, name, title, class/spec, and a short bio for each.$q$, $q$A new Bios tab introduces the team's raid officers -- photo, name, title, class/spec, and a short bio for each.$q$, $q$3.40.0$q$, false, '2026-07-16 12:00 America/New_York'),
  ($q$my-wishlist-tag-any-item-not-just-your-one-bis-pick$q$, $q$My Wishlist: tag any item, not just your one BiS pick$q$, 'Feature', $q$Your profile now has a Wishlist tab where you can tag any item in your armor type as BiS, Good, OK, Catalyst Only, or Pass, with an optional note -- separate from (and shown alongside) the officer's single BiS pick per slot.$q$, $q$Your profile now has a Wishlist tab where you can tag any item in your armor type as BiS, Good, OK, Catalyst Only, or Pass, with an optional note -- separate from (and shown alongside) the officer's single BiS pick per slot.$q$, $q$3.42.0$q$, false, '2026-07-20 12:00 America/New_York'),
  ($q$wishlist-tab-reorganized-into-collapsible-slot-cards$q$, $q$Wishlist tab reorganized into collapsible slot cards$q$, 'Change', $q$The Wishlist tab used to be one long scroll.$q$, $q$The Wishlist tab used to be one long scroll. Each gear slot is now its own collapsible card with a colored dot showing how many items you've tagged there, and Other Sources (M+/Crafted) is now a single card instead of repeating on every slot.$q$, $q$3.44.0$q$, false, '2026-07-20 12:00 America/New_York'),
  ($q$wishlist-completeness-indicator$q$, $q$Wishlist completeness indicator$q$, 'Feature', $q$Your Wishlist tab now shows "N/16 slots tagged" so you can see at a glance whether you've covered every gear slot -- it turns green once everything's covered and lists what's missing otherwise.$q$, $q$Your Wishlist tab now shows "N/16 slots tagged" so you can see at a glance whether you've covered every gear slot -- it turns green once everything's covered and lists what's missing otherwise.$q$, $q$3.45.0$q$, false, '2026-07-20 12:00 America/New_York'),
  ($q$bis-list-now-shows-items-in-the-right-order$q$, $q$BiS List now shows items in the right order$q$, 'Fix', $q$Your BiS List (on your profile and the officer's Roster view) was sometimes showing gear in a random order instead of head-to-toe.$q$, $q$Your BiS List (on your profile and the officer's Roster view) was sometimes showing gear in a random order instead of head-to-toe. It now always sorts Head, Neck, Shoulder, Back, Chest, Wrist, Hands, Waist, Legs, Feet, Finger 1, Finger 2, Trinket 1, Trinket 2, Weapon, Off Hand.$q$, $q$3.45.1$q$, false, '2026-07-20 12:00 America/New_York'),
  ($q$this-news-tab$q$, $q$This News tab$q$, 'Feature', $q$You're looking at it -- a new News tab with a running feed of what's shipped, newest first.$q$, $q$You're looking at it -- a new News tab with a running feed of what's shipped, newest first. Click an entry to expand a short write-up. The red dot on the nav item clears once you visit.$q$, $q$3.46.0$q$, false, '2026-07-20 12:00 America/New_York'),
  ($q$season-2-loot-is-in-the-catalog$q$, $q$Season 2 loot is in the catalog$q$, 'Change', $q$The Venomous Abyss item list has been imported behind the scenes -- officers can already see it in the Priority tab and BiS picker.$q$, $q$The Venomous Abyss item list has been imported behind the scenes -- officers can already see it in the Priority tab and BiS picker. It'll show up in your Wishlist once Season Settings switches over to the new tier.$q$, $q$3.47.0$q$, false, '2026-07-22 12:00 America/New_York'),
  ($q$priority-tab-and-wishlist-got-a-visual-refresh$q$, $q$Priority tab and Wishlist got a visual refresh$q$, 'Change', $q$Item rows in the Priority tab and your Wishlist now show a larger item icon next to the name, with stat pills (Crit/Haste/Mastery/Vers, whichever the item actually rolls) and the boss it drops from laid out more clearly.$q$, $q$Item rows in the Priority tab and your Wishlist now show a larger item icon next to the name, with stat pills (Crit/Haste/Mastery/Vers, whichever the item actually rolls) and the boss it drops from laid out more clearly.$q$, $q$3.47.3$q$, false, '2026-07-23 12:00 America/New_York'),
  ($q$new-qualification-checks-for-m-exclusion$q$, $q$New qualification checks for M+ exclusion$q$, 'Change', $q$Requesting exclusion from the weekly M+ requirement now asks you to confirm you're 6/6 Myth in every M+ obtainable slot and to select how many of your 3 gem sockets (Helm/Bracer/Belt) are filled -- you need at least 2 of 3 to qualify.$q$, $q$Requesting exclusion from the weekly M+ requirement now asks you to confirm you're 6/6 Myth in every M+ obtainable slot and to select how many of your 3 gem sockets (Helm/Bracer/Belt) are filled -- you need at least 2 of 3 to qualify. An officer still reviews every request before approving.$q$, $q$3.48.0$q$, false, '2026-07-23 12:00 America/New_York'),
  ($q$see-who-s-already-signed-up-when-picking-your-class$q$, $q$See who's already signed up when picking your class$q$, 'Feature', $q$Step 3 of Sign Up now shows who else already plays the class you pick.$q$, $q$Step 3 of Sign Up now shows who else already plays the class you pick. If you're signing up as Tank or Healer, you'll also see a heads up if the team already has enough -- you can still sign up either way, but it's worth considering DPS as backup or talking to an officer first.$q$, $q$3.49.13$q$, false, '2026-07-25 12:00 America/New_York'),
  ($q$clear-my-wishlist-button$q$, $q$Clear My Wishlist button$q$, 'Feature', $q$Your Wishlist tab now has a Clear My Wishlist button that resets everything in one go -- every gear-slot tag and Other Sources pick -- instead of removing each one by hand.$q$, $q$Your Wishlist tab now has a Clear My Wishlist button that resets everything in one go -- every gear-slot tag and Other Sources pick -- instead of removing each one by hand. It asks you to confirm first, and only works while wishlist editing is open.$q$, $q$3.49.37$q$, false, '2026-07-31 12:00 America/New_York'),
  ($q$heads-up-when-a-slot-s-bis-already-comes-from-other-sources$q$, $q$Heads up when a slot's BiS already comes from Other Sources$q$, 'Feature', $q$If you've tagged M+, Crafted, or Catalyst as your BiS for a slot under Other Sources, opening that slot's own raid-drop card now tells you so -- easy to miss otherwise, since the two picks live on separate cards.$q$, $q$If you've tagged M+, Crafted, or Catalyst as your BiS for a slot under Other Sources, opening that slot's own raid-drop card now tells you so -- easy to miss otherwise, since the two picks live on separate cards.$q$, $q$3.49.48$q$, false, '2026-08-03 12:00 America/New_York'),
  ($q$wga-priority-loot-addon-linked-from-wishlist-and-loot-pages$q$, $q$WGA Priority Loot addon linked from Wishlist and Loot pages$q$, 'Feature', $q$Your Wishlist tab now links the WGA Priority Loot addon -- install it in-game to see your Priority rank on items as they drop.$q$, $q$Your Wishlist tab now links the WGA Priority Loot addon -- install it in-game to see your Priority rank on items as they drop. Officers running the Priority Order system need it; it's optional for raiders.$q$, $q$3.49.48$q$, false, '2026-08-03 12:00 America/New_York'),
  ($q$wishlist-bis-now-only-show-weapons-your-class-can-use$q$, $q$Wishlist/BiS now only show weapons your class can use$q$, 'Fix', $q$The Weapon and Off Hand rows in your Wishlist and the officer BiS grid used to mix in every class's weapons and shields.$q$, $q$The Weapon and Off Hand rows in your Wishlist and the officer BiS grid used to mix in every class's weapons and shields. They're now filtered to what your class can actually equip -- e.g. a Mage no longer sees Maces or Polearms, and shields only show for Warrior/Paladin/Shaman. Also filtered out a handful of healer-only and tank-only trinkets from showing to the wrong role.$q$, $q$3.49.49$q$, false, '2026-08-03 12:00 America/New_York'),
  ($q$raider-io-sync-tier-progress-priority-weighting$q$, $q$Raider.IO sync + tier-progress priority weighting$q$, 'Feature', $q$Your BiS List now has a Sync from Raider.IO button that checks your equipped gear and auto-marks tagged tier pieces as obtained, and shows your tier-set progress as a Tier: N/5 badge.$q$, $q$Your BiS List now has a Sync from Raider.IO button that checks your equipped gear and auto-marks tagged tier pieces as obtained, and shows your tier-set progress as a Tier: N/5 badge. Priority order for tier-token drops now factors that in too -- raiders closer to their next set bonus rank higher.$q$, $q$3.51.0$q$, false, '2026-08-04 12:00 America/New_York'),
  ($q$history-tab-now-shows-what-you-were-working-on$q$, $q$History tab now shows what you were working on$q$, 'Feature', $q$If a boss wasn't killed before a season got archived, the History tab now shows its Mythic pull count and best % alongside that season's kill count, instead of losing that progress.$q$, $q$If a boss wasn't killed before a season got archived, the History tab now shows its Mythic pull count and best % alongside that season's kill count, instead of losing that progress.$q$, $q$3.51.1$q$, false, '2026-08-04 12:00 America/New_York'),
  ($q$claim-your-character-prompt-stops-nagging-raiders-who-don-t$q$, $q$"Claim your character" prompt stops nagging raiders who don't need it$q$, 'Fix', $q$It no longer pops up if you're already claimed on a different team, and now has an "I don't have a character yet" option that dismisses it for good.$q$, $q$It no longer pops up if you're already claimed on a different team, and now has an "I don't have a character yet" option that dismisses it for good.$q$, $q$3.52.0$q$, false, '2026-08-05 12:00 America/New_York'),
  ($q$a-nudge-to-fill-out-your-wishlist-when-you-re-new$q$, $q$A nudge to fill out your wishlist when you're new$q$, 'Feature', $q$If you joined the roster recently and haven't tagged anything in your Wishlist yet, you'll now see a welcome banner on your profile pointing you to the Wishlist tab.$q$, $q$If you joined the roster recently and haven't tagged anything in your Wishlist yet, you'll now see a welcome banner on your profile pointing you to the Wishlist tab. It goes away as soon as you add your first entry (or after 30 days).$q$, $q$3.56.0$q$, false, '2026-08-08 12:00 America/New_York'),
  ($q$set-a-bonus-roll-target-on-your-profile$q$, $q$Set a Bonus Roll target on your profile$q$, 'Feature', $q$Planning to spend your weekly Bonus Roll on a specific boss until you get the item(s) you're after?$q$, $q$Planning to spend your weekly Bonus Roll on a specific boss until you get the item(s) you're after? Set it on your profile now so officers have a heads-up when making loot calls. It's purely informational -- it has no effect on Priority order. Officers see it as a badge on the Roster tab.$q$, $q$3.59.0$q$, false, '2026-08-09 12:00 America/New_York'),
  ($q$catalyst-only-wishlist-status-hidden-where-it-can-t-apply$q$, $q$"Catalyst Only" wishlist status hidden where it can't apply$q$, 'Fix', $q$It no longer shows on the actual tier piece row (the tier item itself never goes into the catalyst -- it's the other, non-tier item for that slot you'd catalyze) or on Neck/Finger/Trinket/Weapon/Off Hand rows, since the catalyst only ever touches armor slots.$q$, $q$It no longer shows on the actual tier piece row (the tier item itself never goes into the catalyst -- it's the other, non-tier item for that slot you'd catalyze) or on Neck/Finger/Trinket/Weapon/Off Hand rows, since the catalyst only ever touches armor slots.$q$, $q$3.60.17$q$, false, '2026-08-18 12:00 America/New_York'),
  ($q$a-guild-page-above-the-three-teams$q$, $q$A guild page above the three teams$q$, 'Feature', $q$There's now a page for the guild rather than any one team, at guild.html, reachable from the Guild link in the nav.$q$, $q$There's now a page for the guild rather than any one team, at guild.html, reachable from the Guild link in the nav. It lists the teams, says which are taking signups, and links straight to each one's roster or signup form. More is coming to it: live streams across all teams, news, and reporting a BoE you found without having to pick a team page first. If you arrive at the site without a team in the link, you land here instead of the old three-button popup. Nothing changes if you're signed in and claimed on one team: you still go straight to your own roster.$q$, $q$3.69.0$q$, false, '2026-08-27 12:00 America/New_York'),
  ($q$report-a-found-boe-right-from-the-website$q$, $q$Report a found BoE right from the website$q$, 'Feature', $q$Found a BoE while raiding with the guild?$q$, $q$Found a BoE while raiding with the guild? There's a BoE tab in the nav now -- fill in your character, the item, its track and upgrade rank, and officers take it from there. The team field defaults to whichever team's page you're on, but change it if you're not on any team's roster or you raided with a different team that night. Once it lists and sells, you get a cut of the sale (or you can donate it to the guild bank instead). Officers, BoE managers, and site admins track every find end to end -- listed, sold, paid, or retired -- on its own BoE Sales page, reachable from the Guild page's nav.$q$, $q$3.81.2$q$, false, '2026-09-03 12:00 America/New_York'),
  ($q$report-a-boe-and-follow-it-on-one-page$q$, $q$Report a BoE and follow it, on one page$q$, 'Feature', $q$The BoE form and the record of what happened to every find now live together on the BoE page.$q$, $q$The BoE form and the record of what happened to every find now live together on the BoE page. Report a drop at the top: your character, the item, its track and upgrade rank, and whether you'd rather donate your cut to the guild. Still no login needed. Underneath, sign in and you'll see the finds reported under your own character, from found through listed and sold to paid, so you can tell where yours got to without asking an officer. The Reporting for team field asks which team you raided with instead of assuming, unless you came from a link that already says. Old links all still work: the pinned per-team Discord links and the guild page's BoE link land you in the same place.$q$, $q$3.88.0$q$, true, '2026-09-03 12:00 America/New_York'),
  ($q$raid-calendar-a-day-view-for-every-raid-night$q$, $q$Raid Calendar: a day view for every raid night$q$, 'Feature', $q$There's a Calendar now, reachable from the nav and previewed on your Home page -- it lays out your team's raid nights for the month, color-coded by status, and each date responds to your own RSVP overrides.$q$, $q$There's a Calendar now, reachable from the nav and previewed on your Home page -- it lays out your team's raid nights for the month, color-coded by status, and each date responds to your own RSVP overrides. Click any raid day, on the full page or the Home widget, to open that night's own page: your own status control sits at the top (Late, Leaving Early, Tentative, or Absent, with a note), below that is everyone's status for the night grouped by role, and in/out/haven't-answered counts up top. Arrows move you to the day before or after, and the page has its own link, so you can send someone straight to a specific raid night. Officers can now correct another raider's status from that list too, always with a note so the raider can see why it changed.$q$, $q$3.93.0$q$, false, '2026-09-07 12:00 America/New_York');
